from solution import maximum


def test_issue_example_second_larger():
    """Example: maximum(5,10) == 10."""
    assert maximum(5, 10) == 10  # 5<10 so 10


def test_issue_first_larger():
    """Maximum returns the larger of a and b."""
    assert maximum(10, 5) == 10  # 10-5=5>0 so 10


def test_issue_equal_numbers():
    """Maximum of two equal numbers is that number."""
    assert maximum(7, 7) == 7  # 7-7=0 so 7


def test_issue_both_negative():
    """Maximum returns the larger of two negatives."""
    assert maximum(-5, -10) == -5  # -5-(-10)=5>0 so -5


def test_issue_negative_and_positive():
    """Maximum of a negative and a positive is the positive."""
    assert maximum(-3, 2) == 2  # 2-(-3)=5>0 so 2


def test_issue_zero_vs_negative():
    """Maximum of 0 and a negative is 0."""
    assert maximum(0, -1) == 0  # 0-(-1)=1>0 so 0


def test_issue_floats():
    """Maximum works for floats."""
    assert maximum(2.5, 3.5) == 3.5  # 3.5-2.5=1.0>0 so 3.5


def test_issue_mixed_int_and_float():
    """Maximum works for mixed int and float."""
    assert maximum(5, 4.9) == 5  # 5-4.9=0.1>0 so 5


def test_contract_returns_larger():
    """Maximum returns the larger of the two numbers."""
    assert maximum(1000000, 999999) == 1000000  # 1000000-999999=1>0 so 1000000


def test_contract_order_does_not_matter():
    """Maximum does not depend on argument order."""
    assert maximum(3, 8) == maximum(8, 3) == 8  # 8-3=5>0 so 8
